SELECT DISTINCT ?graph ?subject ?predicate ?object
WHERE {
  VALUES ?graph {
    <urn:graphragprov:unit:u_1de57ccd6294dbca>
    <urn:graphragprov:unit:u_40b3825dc010be23>
    <urn:graphragprov:unit:u_882ece6fcf95e822>
